let inp = {};
try { inp = $input.first().json ?? {}; } catch (e) { inp = {}; }
let trig = {};
try { trig = $('Trigger').first().json ?? {}; } catch (e) { trig = {}; }
const html = String(inp.data ?? '');
const noScripts = html.replace(/<script[\s\S]*?<\/script\s*>/gi, ' ').replace(/<style[\s\S]*?<\/style\s*>/gi, ' ');
const pageText = noScripts.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 6000);
const fallback = String(trig.text ?? '').slice(0, 6000);
return [{ json: { url: String(trig.url ?? ''), title: String(trig.title ?? ''), text: (fallback + '\n' + pageText).slice(0, 6000) } }];

const raw = $input.first().json ?? {};
const parsed = raw.output ?? raw;
let src = {};
try { src = $('Code ToText').first().json ?? {}; } catch (e) { src = {}; }
const ET = ['Full-time', 'Contract', 'Internship', 'Part-time'];
const WA = ['Remote', 'Hybrid', 'Onsite'];
const num = (x) => (typeof x === 'number' && isFinite(x) ? x : null);
const dom = String(src.url ?? '').toLowerCase();
let source = 'Website Perusahaan';
if (dom.includes('jobstreet')) source = 'JobStreet';
else if (dom.includes('glints')) source = 'Glints';
else if (dom.includes('linkedin')) source = 'LinkedIn';
else if (dom.includes('dealls')) source = 'Dealls';
const company = String(parsed.company ?? '').trim();
const role = String(parsed.role ?? '').trim();
const text = String(src.text ?? '');
return [{ json: {
  company,
  role,
  status: 'Applied',
  source,
  job_url: String(src.url ?? ''),
  location: String(parsed.location ?? '').trim() || null,
  employment_type: ET.includes(parsed.employment_type) ? parsed.employment_type : null,
  work_arrangement: WA.includes(parsed.work_arrangement) ? parsed.work_arrangement : null,
  salary_min: num(parsed.salary_min),
  salary_max: num(parsed.salary_max),
  job_description: text.slice(0, 4000),
  notes: String(src.title ?? '') || null
} }];

const item = $input.first().json ?? {};
let build = {};
try { build = $('Code BuildPayload').first().json ?? {}; } catch (e) { build = {}; }
if (typeof item.ok === 'boolean') {
  return [{ json: { ...item, company: build.company ?? item.company ?? null, role: build.role ?? item.role ?? null } }];
}
const url = String(item.job_url ?? item.url ?? '').trim();
if (!/^https?:\/\//i.test(url)) return [{ json: { ok: false, error: 'url wajib' } }];
const text = String(item.job_description ?? item.text ?? '');
if (!text.trim()) return [{ json: { ok: false, error: 'tidak bisa baca halaman' } }];
const company = String(item.company ?? build.company ?? '').trim();
const role = String(item.role ?? build.role ?? '').trim();
if (!company || !role) return [{ json: { ok: false, error: 'company dan role wajib' } }];
return [{ json: { ...item, company, role } }];
